import org.junit.jupiter.api.Test;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.TimeUnit;
public class VerifierProfileProbe {
 static final String[] KEYS={"HOME","USERPROFILE","APPDATA","LOCALAPPDATA","XDG_CONFIG_HOME","XDG_DATA_HOME","XDG_CACHE_HOME","XDG_STATE_HOME","JUSTSEARCH_HOME","JUSTSEARCH_DATA_DIR"};
 static void require(boolean ok,String message){if(!ok)throw new AssertionError(message);}
 @Test void workerAndChild() throws Exception {
   Path profile=Path.of(System.getProperty("verifier.expected"));
   List<String> errors=new ArrayList<>();
   String home=System.getProperty("user.home");
   System.out.println("USER_HOME="+home+" EXPECTED="+profile);
   if(!Path.of(home).startsWith(profile))errors.add("worker user.home="+home);
   for(String k:KEYS){String v=System.getenv(k);System.out.println(k+"="+v);if(v==null||!Path.of(v).startsWith(profile))errors.add("worker "+k+"="+v);}
   for(String k:List.of("justsearch.data.dir","justsearch.home")){String v=System.getProperty(k);System.out.println(k+"="+v);if(v==null||!Path.of(v).startsWith(profile))errors.add(k+"="+v);}
   Path out=Files.createTempFile("verifier-child-", ".properties");
   Process p=new ProcessBuilder(Path.of(System.getProperty("java.home"),"bin","java").toString(),"-cp",System.getProperty("java.class.path"),"VerifierProfileProbe$Child").redirectOutput(out.toFile()).redirectError(ProcessBuilder.Redirect.INHERIT).start();
   try{require(p.waitFor(30,TimeUnit.SECONDS),"child timed out");require(p.exitValue()==0,"child failed");Properties props=new Properties();try(var in=Files.newInputStream(out)){props.load(in);}for(String k:KEYS){String v=props.getProperty(k);if(v==null||!Path.of(v).startsWith(profile)||!Objects.equals(v,System.getenv(k)))errors.add("child "+k+"="+v);}System.out.println("ACCEPTED_JAVA_CHILD_USER_HOME_GAP="+props.getProperty("java.user.home"));}finally{p.destroyForcibly();p.waitFor();Files.deleteIfExists(out);}
   require(errors.isEmpty(),String.join("; ",errors));
 }
 public static class Child {public static void main(String[] args)throws Exception{Properties p=new Properties();for(String k:KEYS)p.setProperty(k,Objects.toString(System.getenv(k),""));p.setProperty("java.user.home",System.getProperty("user.home"));p.store(System.out,null);}}
}

